from __future__ import annotations
from itertools import product
from typing import Dict, Iterable, Set, Tuple
State = Tuple[Tuple[int, ...], int]

def path(n: int) -> Dict[int, Set[int]]:
    return {v: {w for w in range(n) if abs(v-w) == 1} for v in range(n)}

def ranks(graph: Dict[int, Set[int]], k: int) -> Dict[State, int]:
    vertices = tuple(graph)
    states = [(c, r) for c in product(vertices, repeat=k) for r in vertices]
    won = {s for s in states if s[1] in s[0]}
    rank = {s: 0 for s in won}
    stage = 0
    while True:
        new = set(won)
        for cops, robber in states:
            choices = [{v, *graph[v]} for v in cops]
            for moved in product(*choices):
                replies = {robber, *graph[robber]}
                if robber in moved or all((moved, r) in won for r in replies):
                    new.add((cops, robber)); break
        if new == won: return rank
        stage += 1
        for s in new - won: rank[s] = stage
        won = new

if __name__ == "__main__":
    result = ranks(path(7), 1)
    histogram: Dict[int, int] = {}
    for value in result.values(): histogram[value] = histogram.get(value, 0) + 1
    print("First-entry rank histogram for one cop on P7:", histogram)

from __future__ import annotations
from itertools import product
from typing import Dict, Set, Tuple

def cycle(n: int) -> Dict[int, Set[int]]:
    return {v: {(v-1) % n, (v+1) % n} for v in range(n)}

def compare_orders(n: int = 5) -> None:
    g = cycle(n); captured = {(c, r) for c in range(n) for r in range(n) if c == r}
    correct, reversed_order = set(captured), set(captured)
    for c, r in product(range(n), repeat=2):
        cop_moves, robber_moves = {c, *g[c]}, {r, *g[r]}
        # Correct: one committed cop move must withstand every reply.
        if any(c2 == r or all((c2, r2) in captured for r2 in robber_moves) for c2 in cop_moves):
            correct.add((c, r))
        # Incorrect game: a different cop move may be chosen after each reply.
        if all(any(c2 == r or (c2, r2) in captured for c2 in cop_moves) for r2 in robber_moves):
            reversed_order.add((c, r))
    print("Correct one-round states:", len(correct))
    print("States under reversed quantifiers:", len(reversed_order))
    print("Spurious states:", sorted(reversed_order - correct))

