    vertices = tuple(graph)
    states = tuple((c, r) for c in product(vertices, repeat=k) for r in vertices)
    current = {s for s in states if s[1] in s[0]}
    tables = [frozenset(current)]
    while True:
        following = set(current)
        for cops, robber in states:
            if (cops, robber) in following: continue
            cop_choices = [{v, *graph[v]} for v in cops]
            replies = {robber, *graph[robber]}
            if any(robber in moved or all((moved, reply) in current for reply in replies)
                   for moved in product(*cop_choices)):
                following.add((cops, robber))
        if following == current: return tables
        current = following
        tables.append(frozenset(current))

from __future__ import annotations
from itertools import product
from typing import Dict, Mapping, Set, Tuple
State = Tuple[Tuple[int, ...], int]
Graph = Dict[int, Set[int]]

def extract_ranked_strategy(graph: Graph, k: int) -> Tuple[Dict[State, int], Dict[State, Tuple[int, ...]]]:
    vertices = tuple(graph)
    states = tuple((c, r) for c in product(vertices, repeat=k) for r in vertices)
    won = {s for s in states if s[1] in s[0]}
    rank = {s: 0 for s in won}; strategy: Dict[State, Tuple[int, ...]] = {}; stage = 0
    while True:
        additions: Dict[State, Tuple[int, ...]] = {}
        for cops, robber in states:
            if (cops, robber) in won: continue
            replies = {robber, *graph[robber]}
            for moved in product(*[{v, *graph[v]} for v in cops]):
                if robber in moved or all((moved, reply) in won for reply in replies):
                    additions[(cops, robber)] = moved; break
        if not additions: return rank, strategy
        stage += 1
        for state, move in additions.items(): rank[state] = stage; strategy[state] = move
        won.update(additions)

from __future__ import annotations
from itertools import combinations_with_replacement
from typing import Dict, Iterator, Set, Tuple
Configuration = Tuple[int, ...]

def multiset_configurations(vertices: int, k: int) -> Iterator[Configuration]:
    yield from combinations_with_replacement(range(vertices), k)

def canonical(configuration: Tuple[int, ...]) -> Configuration:
    return tuple(sorted(configuration))

def quotient_size(vertices: int, k: int) -> Tuple[int, int]:
    labeled = vertices ** k
    reduced = sum(1 for _ in multiset_configurations(vertices, k))
    return labeled, reduced

if __name__ == "__main__":
    print("labeled, permutation-quotiented:", quotient_size(12, 4))

